# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().

reset_julia_backend_state <- function() {
  original_state <- FIMS:::.fims_julia_backend_state$initialized
  withr::defer(
    FIMS:::.fims_julia_backend_state$initialized <- original_state,
    envir = parent.frame()
  )
  FIMS:::.fims_julia_backend_state$initialized <- FALSE
}

test_that("Julia backend package scaffolding exists", {
  backend_root <- normalizePath(
    testthat::test_path("..", "..", "inst", "julia", "FIMSBackend"),
    winslash = "/",
    mustWork = TRUE
  )

  #' @description Test that the Julia backend Project.toml exists.
  expect_true(file.exists(file.path(backend_root, "Project.toml")))
  #' @description Test that the Julia backend top-level module exists.
  expect_true(file.exists(file.path(backend_root, "src", "FIMSBackend.jl")))
  #' @description Test that the Julia backend selectivity module exists.
  expect_true(file.exists(file.path(backend_root, "src", "modules", "selectivity.jl")))
  #' @description Test that the Julia backend recruitment module exists.
  expect_true(file.exists(file.path(backend_root, "src", "modules", "recruitment.jl")))
  #' @description Test that the Julia backend population module exists.
  expect_true(file.exists(file.path(backend_root, "src", "modules", "population.jl")))
})

test_that("Julia backend helpers return package paths", {
  backend_path <- FIMS:::julia_backend_package_path()
  module_path <- FIMS:::julia_backend_module_path()

  #' @description Test that the Julia backend package path is a character scalar.
  expect_type(backend_path, "character")
  #' @description Test that the Julia backend module path is a character scalar.
  expect_type(module_path, "character")
})

test_that("Julia backend input preparation preserves existing initialize_fims output shape", {
  reset_julia_backend_state()
  data <- FIMS::FIMSFrame(data_big)
  parameters <- FIMS::setup_default_parameters(data = data)
  result <- FIMS::initialize_fims(parameters = parameters, data = data, backend = "julia")
  julia_input <- attr(result, "julia_input")

  #' @description Test that Julia backend initialization still returns the standard two-element list.
  expect_named(result, c("parameters", "model"))
  #' @description Test that Julia backend initialization stores backend metadata as an attribute.
  expect_equal(attr(result, "backend"), "julia")
  #' @description Test that Julia backend initialization stores Julia input metadata as an attribute.
  expect_true(is.list(julia_input))
  #' @description Test that Julia backend initialization stores Julia input data and parameters.
  expect_named(julia_input, c("data", "parameters"))
  #' @description Test that Julia backend input preserves the number of modeled years.
  expect_equal(julia_input[["data"]][["n_years"]], get_n_years(data))
  #' @description Test that Julia backend input preserves the modeled age bins.
  expect_equal(julia_input[["data"]][["ages"]], get_ages(data))
  #' @description Test that Julia backend input now includes weight-at-age and maturity matrices.
  expect_true(all(c("weights_at_age", "maturity_at_age") %in% names(julia_input[["data"]])))
  #' @description Test that Julia backend input includes serialized population and observation values.
  expect_true(all(c("proportion_female", "observed_catch") %in% names(julia_input[["data"]])))
  #' @description Test that Julia backend parameters are serialized to the named structure expected by the Julia objective scaffold.
  expect_true(all(c("log_Fmort", "log_M", "log_init_naa", "log_rzero", "logit_steep") %in% names(julia_input[["parameters"]])))
  #' @description Test that the Julia backend weight-at-age matrix has one row per modeled year and one column per age.
  expect_equal(dim(julia_input[["data"]][["weights_at_age"]]), c(get_n_years(data), get_n_ages(data)))
  #' @description Test that the Julia backend maturity-at-age matrix has one row per modeled year and one column per age.
  expect_equal(dim(julia_input[["data"]][["maturity_at_age"]]), c(get_n_years(data), get_n_ages(data)))
  #' @description Test that the serialized fishing mortality vector spans every year-age cell.
  expect_length(julia_input[["parameters"]][["log_Fmort"]], get_n_years(data) * get_n_ages(data))
  #' @description Test that the serialized natural mortality vector spans every year-age cell.
  expect_length(julia_input[["parameters"]][["log_M"]], get_n_years(data) * get_n_ages(data))

  clear()
})

test_that("Julia backend serializer omits unavailable observed data entries", {
  reset_julia_backend_state()
  data <- data_big |>
    dplyr::filter(!.data$type %in% c("catch", "index", "age_comp")) |>
    FIMS::FIMSFrame()
  parameters <- FIMS::setup_default_parameters(data = data)
  julia_input <- FIMS:::prepare_julia_backend_input(parameters = parameters, data = data)

  #' @description Test that missing catch data are omitted from the Julia serializer output.
  expect_false("observed_catch" %in% names(julia_input[["data"]]))
  #' @description Test that missing index data are omitted from the Julia serializer output.
  expect_false("observed_index" %in% names(julia_input[["data"]]))
  #' @description Test that missing age-composition data are omitted from the Julia serializer output.
  expect_false("observed_age_comp" %in% names(julia_input[["data"]]))

  clear()
})

test_that("Julia backend serializer rejects unsupported multi-fleet observation inputs", {
  reset_julia_backend_state()
  multi_fleet_data <- dplyr::bind_rows(
    data_big,
    data_big |>
      dplyr::filter(.data$fleet == "fleet1") |>
      dplyr::mutate(fleet = "fleet2")
  ) |>
    FIMS::FIMSFrame()
  parameters <- FIMS::setup_default_parameters(data = multi_fleet_data)

  #' @description Test that the experimental Julia serializer errors on unsupported multiple catch fleets.
  expect_error(
    FIMS:::prepare_julia_backend_input(parameters = parameters, data = multi_fleet_data),
    regexp = "currently supports only one catch fleet"
  )

  clear()
})

test_that("Julia backend input errors in fit_fims until the fit bridge is complete", {
  reset_julia_backend_state()
  data <- FIMS::FIMSFrame(data_big)
  parameters <- FIMS::setup_default_parameters(data = data)
  result <- FIMS::initialize_fims(parameters = parameters, data = data, backend = "julia")

  #' @description Test that Julia backend input triggers the current explicit fit_fims guard.
  expect_error(
    FIMS::fit_fims(result, optimize = TRUE),
    regexp = "not yet fully wired into"
  )

  clear()
})

test_that("Julia backend initialization stays shaped correctly when Julia startup is disabled", {
  reset_julia_backend_state()
  withr::local_options(list(FIMS.disable_julia = TRUE))
  data <- FIMS::FIMSFrame(data_big)
  parameters <- FIMS::setup_default_parameters(data = data)
  result <- FIMS::initialize_fims(parameters = parameters, data = data, backend = "julia")

  #' @description Test that disabling Julia startup still preserves the standard initialize_fims output shape.
  expect_named(result, c("parameters", "model"))
  #' @description Test that disabling Julia startup still preserves Julia input metadata.
  expect_true(is.list(attr(result, "julia_input")))

  clear()
})

test_that("Julia backend initialization assigns prepared input when Julia startup succeeds", {
  reset_julia_backend_state()
  data <- FIMS::FIMSFrame(data_big)
  parameters <- FIMS::setup_default_parameters(data = data)
  assigned <- FALSE
  assigned_input <- NULL

  testthat::local_mocked_bindings(
    initialize_julia_backend = function(...) TRUE,
    assign_julia_backend_input = function(x) {
      assigned <<- TRUE
      assigned_input <<- x
      invisible(TRUE)
    },
    .package = "FIMS"
  )

  result <- FIMS::initialize_fims(parameters = parameters, data = data, backend = "julia")

  #' @description Test that the Julia assignment branch is reached when Julia startup succeeds.
  expect_true(assigned)
  #' @description Test that the Julia assignment branch receives the same serialized input attached to the returned object.
  expect_equal(assigned_input, attr(result, "julia_input"))
  #' @description Test that the Julia backend success branch still preserves backend metadata.
  expect_equal(attr(result, "backend"), "julia")

  clear()
})
